const DICTIONARIES: Record<Locale, Messages> = {
  'zh-CN': ZH_CN_MESSAGES,
  en: EN_MESSAGES,
  ja: JA_MESSAGES,
  ko: KO_MESSAGES,
  de: DE_MESSAGES,
  fr: FR_MESSAGES,
  es: ES_MESSAGES,
  pt: PT_MESSAGES,
  ru: RU_MESSAGES,
}

export const MESSAGE_KEYS = Object.freeze(Object.keys(EN_MESSAGES) as MessageKey[])

export function normalizeLocale(value: string | null | undefined): Locale {
  const normalized = value?.trim().toLocaleLowerCase()
  if (normalized?.startsWith('zh')) return 'zh-CN'
  const language = normalized?.split(/[-_]/)[0]
  if (language && SUPPORTED_LOCALES.includes(language as Locale)) return language as Locale
  return DEFAULT_LOCALE
}

export function getLocaleOptions(): Array<{ label: string; value: Locale }> {
  return [
    { label: '简体中文', value: 'zh-CN' },
    { label: 'English', value: 'en' },
    { label: '日本語 · Beta', value: 'ja' },
    { label: '한국어 · Beta', value: 'ko' },
    { label: 'Deutsch · Beta', value: 'de' },
    { label: 'Français · Beta', value: 'fr' },
    { label: 'Español · Beta', value: 'es' },
    { label: 'Português · Beta', value: 'pt' },
    { label: 'Русский · Beta', value: 'ru' },
  ]
}

export function translate(
  locale: Locale,
  key: MessageKey,
  values: Readonly<Record<string, string | number>> = {},
): string {
  return Object.entries(values).reduce(
    (message, [name, value]) => message.replaceAll(`{${name}}`, String(value)),
    DICTIONARIES[locale][key],
  )
}
